function macMenus(){return `<nav class="mac-menubar" aria-label="Application menu" role="menubar">${Object.keys(applicationMenus).map((name,i)=>`<button role="menuitem" aria-haspopup="menu" aria-expanded="false" data-app-menu="${name}" tabindex="${i===0?'0':'-1'}" class="${i===0?'app-menu-name':''}">${name}</button>`).join('')}</nav>`}
function shell(content){document.getElementById('app').innerHTML=`${macMenus()}<header class="titlebar"><div class="traffic" aria-hidden="true"><i></i><i></i><i></i></div><span class="window-caption">ChoscorDB <span class="muted">— ${names[page]}</span></span><span class="window-tail" aria-hidden="true"></span></header><div class="shell">${sidebar()}<main class="main">${content}</main></div><footer class="statusbar"><span><span class="dot"></span> Personal workspace <span style="margin:0 12px">/</span> All data shown is sample data</span><span>ChoscorDB · Prototype</span></footer><div id="modal-root"></div><div id="toast" class="toast hidden" role="status"></div>`}
function welcome(){return `<div class="content welcome"><div class="workspace-empty"><span class="empty-database-icon">${icon('db')}</span><h1>No database open</h1><p>Select a connection in the sidebar or create a new one.</p></div></div>`}
function connectionForm(sqlite=false){return `<form class="connection-form" id="connection-form" data-driver="${sqlite?'sqlite':'postgres'}"><p class="small connection-intro">Connect to a server or open a local database file.</p><div class="driver-picker" aria-label="Database driver"><button type="button" data-action="connection-driver" data-driver="postgres" class="${!sqlite?'active':''}" aria-pressed="${!sqlite}">${icon('db')} PostgreSQL</button><button type="button" data-action="connection-driver" data-driver="sqlite" class="${sqlite?'active':''}" aria-pressed="${sqlite}">${icon('db')} SQLite</button></div>${field('Connection name',sqlite?'New SQLite connection':'New PostgreSQL connection','text','required id="profile-name"')}${sqlite?`${field('Database file','~/Databases/sandbox.db','text','required id="database-path"')}<div class="settings-row"><div><h3>Open read-only</h3><p>Browse safely without modifying the file.</p></div><input class="toggle" type="checkbox" checked aria-label="Open read-only"></div>`:`<div class="form-grid">${field('Host','localhost','text','required id="database-host"')}${field('Port','5432','number','required min="1" max="65535"')}${field('Database','commerce','text','required id="database-name"')}${field('Username','postgres','text','required')}</div>${field('Password','','password','autocomplete="new-password" placeholder="Enter your database password"')}<label class="row small muted"><input type="checkbox" checked> Save password in system credential manager</label><details class="security-options"><summary>${icon('shield')} TLS & security <span class="small muted">Verify full</span></summary><div class="security-fields">${select('TLS mode',['Verify full · recommended','Require encryption','Disable · local development'])}${field('CA certificate (optional)','','text','placeholder="Use system certificates"')}</div></details>` }<div id="connection-feedback" style="margin-top:18px" role="status"></div><div class="connection-footer row space">${btn('Test connection','test-connection')}<div class="actions">${btn('Cancel','close-modal')}${btn('Save profile','save-profile')}<button class="primary" type="submit">Save & connect ${icon('arrow')}</button></div></div><details class="prototype-states"><summary class="small muted">Sample error state</summary>${btn('Simulate authentication error','connection-error','ghost')}</details></form>`}
function connection(){return `<div class="content">${heading('Connections','Manage PostgreSQL servers and local SQLite databases.',btn(icon('plus')+' New connection','new-connection','primary'))}<div class="card empty"><div class="db-icon">${icon('db')}</div><h2>Open a database connection</h2><p>Connection settings open in a dialog, keeping your workspace in place.</p><div class="actions" style="justify-content:center;margin-top:20px">${btn(icon('plus')+' New connection','new-connection','primary')}${btn('Focus connections','focus-connections')}</div></div></div>`}
let editingConnectionId=null;
function openConnection(sqlite=false){editingConnectionId=null;modal('New connection',connectionForm(sqlite),' ');document.querySelector('.modal').classList.add('connection-modal');document.getElementById('profile-name').focus()}
function saveConnection(connect=false){
  const form=document.getElementById('connection-form');
  if(!form||!form.reportValidity())return;
  const name=form.querySelector('#profile-name').value.trim();
  if(!name){form.querySelector('#profile-name').setCustomValidity('Enter a connection name.');form.reportValidity();return}
  const sqlite=form.dataset.driver==='sqlite';
  const database=sqlite?form.querySelector('#database-path').value.split('/').pop():form.querySelector('#database-name').value;
  const profile={id:editingConnectionId||'profile-'+Date.now(),name,driver:sqlite?'SQLite':'PostgreSQL',database,schema:sqlite?'main':'public',tables:[],views:[]};
  const existing=explorerConnections.findIndex(c=>c.id===profile.id);if(existing>=0){profile.tables=explorerConnections[existing].tables;profile.views=explorerConnections[existing].views;explorerConnections[existing]=profile}else explorerConnections.push(profile);selectedConnection=profile;storeConnectionProfiles();
  closeModal();document.querySelector('.sidebar').outerHTML=sidebar();document.querySelector(`[data-connection="${profile.id}"]`).focus();
  if(connect){saved.pendingSQL='-- '+profile.name+'\nSELECT ';saved.pendingTitle='Untitled query';saved.pendingConnection=profile.id;persist();location.href='workspace.html'}else toast('Connection profile saved.');
}

