function schema(){const allowed=['customers','orders','order_items','products','categories','payments','monthly_revenue','notes','tags','events','sessions','daily_activity'];const requested=new URLSearchParams(location.search).get('table')||(saved.activeObject?.connection===selectedConnection.id?saved.activeObject.table:selectedConnection.tables[0]);const table=allowed.includes(requested)?requested:'customers';return `<div class="content">${heading(table,`${selectedConnection.name} / ${selectedConnection.database} / ${selectedConnection.schema} / ${table}`,`<div class="actions">${btn(icon('refresh')+' Refresh','refresh')}${btn(icon('code')+' Generate SQL','generate-sql','primary')}</div>`)}<div class="grid"><div class="card card-pad"><div class="eyebrow">Object type</div><div class="stat" style="font-size:21px;margin-top:12px">${icon('table')} ${table==='monthly_revenue'?'View':'Table'}</div><div class="stat-label">public schema</div></div><div class="card card-pad"><div class="eyebrow">Columns</div><div class="stat">9</div><div class="stat-label">1 primary key · 2 indexes</div></div><div class="card card-pad"><div class="eyebrow">Row count</div><div class="stat" style="font-size:21px;margin-top:12px">Not counted</div><div class="stat-label">Browse data to fetch rows progressively</div></div></div><div class="tabs" style="margin:24px 0 20px">${['Columns','Indexes','Keys','DDL','Data'].map((t,i)=>`<button data-action="schema-tab" data-tab="${t}" class="${i===0?'active':''}">${t}</button>`).join('')}</div><div id="schema-detail" class="card">${columns()}</div><div class="callout" style="margin-top:23px">${icon('table')}<div>Explore at your own pace.<br><span class="small">Objects load as you expand them. Refresh updates only the selected object.</span></div></div></div>`}
function columns(){return `<div class="table-wrap"><table><thead><tr><th>Column</th><th>Data type</th><th>Nullable</th><th>Default</th><th>Description</th></tr></thead><tbody>${[['id','bigint','No','identity','Primary key'],['name','varchar(255)','No','—','Full name'],['email','varchar(255)','No','—','Unique email address'],['plan','varchar(32)','No',"'starter'",'Subscription plan'],['status','varchar(32)','No',"'active'",'Account status'],['created_at','timestamp','No','now()','Creation time'],['total_spent','numeric(12,2)','Yes','NULL','Lifetime spend'],['metadata','jsonb','Yes',"'{}'",'Additional attributes'],['avatar','bytea','Yes','NULL','Profile image']].map(r=>`<tr>${r.map((v,i)=>`<td class="${i===1||i===3?'mono':' '} ${i===4?'muted':''}">${i===0?icon(v==='id'?'key':'file')+' ':''}${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function history(){return `<div class="content">${heading('Query history','Search previous queries and reopen them in the editor.',btn('Clear history','clear-history'))}<div class="row" style="margin-bottom:24px"><label class="search" style="flex:1">${icon('search')}<input id="history-search" placeholder="Search query text…" aria-label="Search query history"></label><select id="history-status" class="button" aria-label="Filter status"><option>All statuses</option><option>Completed</option><option>Failed</option></select></div><div class="eyebrow" style="margin-bottom:14px">Today · September 13</div><div class="card" id="history-list">${[['SELECT id, name, email, plan, status FROM public.customers','09:42:18','24 ms','8 rows','Completed'],['SELECT date_trunc(\'month\', created_at), SUM(total) FROM orders GROUP BY 1','09:38:05','112 ms','12 rows','Completed'],['SELECT * FROM customer','09:36:22','8 ms','42P01','Failed'],['SELECT * FROM public.products LIMIT 1000','09:30:46','18 ms','48 rows','Completed']].map(([sql,t,d,r,s])=>`<article class="history-item" data-status="${s}" style="padding:21px 24px;border-bottom:1px solid var(--line)"><div class="row space"><span class="mono" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${sql}</span>${btn('Open in editor '+icon('arrow'),'history-open','ghost')}</div><div class="row small muted" style="margin-top:12px">${badge(s,s==='Failed'?'red':'green')}<span>${t}</span><span>·</span><span>Commerce · local</span><span>·</span><span>${d}</span><span>·</span><span>${r}</span></div></article>`).join('')}</div><p class="small" style="margin-top:20px">Queries open in the editor without running. History is kept for 90 days or 10,000 records. <button class="ghost" data-action="open-preferences" data-section="history">Manage history</button></p></div>`}
function exports(){return `<div class="content">${heading('Export results','Choose a format and export the current result.',link('Back to query','workspace'))}<div class="wide-narrow"><div class="card card-pad"><h2>Export results</h2><p class="small">Customer overview · Commerce · local</p><div class="divider"></div><div class="form-grid">${select('File format',['CSV','JSON','JSON Lines','SQL INSERT'],'export-format')}${select('Rows to export',['Current result · 8 sample rows','Current page · 8 sample rows'],'export-scope')}</div>${field('File name','customers-september.csv','text','id="export-name" required')}<div id="csv-options" class="form-grid">${select('Delimiter',['Comma ( , )','Semicolon ( ; )','Tab'],'export-delimiter')}${select('Encoding',['UTF-8'])}</div><div class="settings-row"><div><h3>Include column names</h3><p>Write a header row at the beginning of the file.</p></div><input type="checkbox" class="toggle" id="export-headers" checked aria-label="Include column names"></div><div class="divider"></div><h3>Preview</h3><pre id="export-preview" class="mono" style="padding:16px;background:var(--soft);border-radius:7px;overflow:auto;line-height:1.9">id,name,email,plan,status
1,Olivia Rhye,olivia@acme.test,Pro,active
2,Phoenix Baker,phoenix@acme.test,Team,active</pre><div class="row space" style="margin-top:24px"><span class="small muted">Sample file downloads through your browser.</span>${btn(icon('export')+' Export file','start-export','primary')}</div><div id="export-progress" class="hidden" role="status"><div class="divider"></div><div class="row space"><h3 id="export-status">Preparing export…</h3>${btn('Cancel','cancel-export')}</div><div class="progress"><span id="export-bar" style="width:0%"></span></div><span class="small muted" id="export-count">0 of 8 sample rows</span></div></div><aside><div class="card card-pad"><div class="db-icon">${icon('export')}</div><h2>Small or sprawling.</h2><p class="small">The native app streams results to disk, so a large export doesn’t need a large memory footprint.</p><div class="divider"></div><div class="row small">${icon('check')} CSV, JSON, JSON Lines, SQL</div><div class="row small" style="margin-top:15px">${icon('check')} Cancel at any time</div><div class="row small" style="margin-top:15px">${icon('check')} Publish only on completion</div></div><div class="callout" style="margin-top:20px">${icon('shield')}The prototype exports only its eight sample rows.</div>${btn('Preview export failure','export-error','ghost')}</aside></div></div>`}
function settings(){return `<div class="content">${heading('Preferences','Configure your editor, results, and workspace.',btn('Save preferences','save-preferences','primary'))}<div class="wide-narrow" style="grid-template-columns:170px minmax(0,1fr)"><nav class="menu-list" style="align-self:start"><a href="#appearance" class="active">Appearance</a><a href="#editor">SQL editor</a><a href="#results">Results & execution</a><a href="#history">History & recovery</a><a href="#shortcuts">Keyboard shortcuts</a></nav><div><section class="card card-pad" id="appearance"><h2>Appearance</h2><p class="small">A workspace that feels right, day or night.</p><div class="settings-row"><div><h3>Theme</h3><p>Choose how ChoscorDB looks on your device.</p></div><select id="theme" class="button"><option>Light</option><option>Dark</option><option>System</option></select></div></section><section class="card card-pad" id="editor" style="margin-top:20px"><h2>SQL editor</h2><div class="form-grid" style="margin-top:20px">${select('Font family',['System monospace','Menlo','Consolas'],'editor-font')}${field('Font size','13','number','id="editor-size" min="10" max="24"')}</div><div class="settings-row"><div><h3>Show line numbers</h3><p>Keep your place in longer queries.</p></div><input id="line-numbers" class="toggle" type="checkbox" checked aria-label="Show line numbers"></div></section><section class="card card-pad" id="results" style="margin-top:20px"><h2>Results & execution</h2><div class="form-grid" style="margin-top:20px">${field('Default page size','1000','number','id="setting-page" min="100" max="10000"')}${field('Query timeout (seconds)','30','number','id="setting-timeout" min="1"')}${field('Cache per result (MiB)','64','number','min="1"')}${field('Application cache (MiB)','256','number','min="1"')}</div></section><section class="card card-pad" id="history" style="margin-top:20px"><h2>History & recovery</h2><div class="settings-row"><div><h3>Save query history</h3><p>Retain up to 90 days or 10,000 queries on this device.</p></div><input id="save-history" class="toggle" type="checkbox" checked aria-label="Save query history"></div><div class="settings-row"><div><h3>Restore editor tabs</h3><p>Restore disconnected. Never run queries automatically.</p></div><input id="restore-tabs" class="toggle" type="checkbox" checked aria-label="Restore editor tabs"></div></section><section class="card card-pad" id="shortcuts" style="margin-top:20px"><h2>Keyboard shortcuts</h2>${[['Run selection / current statement','⌘ / Ctrl + Enter'],['Quick switch','⌘ / Ctrl + K'],['Find and replace','⌘ / Ctrl + F'],['Save SQL file','⌘ / Ctrl + S'],['Close dialog','Esc']].map(([n,k])=>`<div class="settings-row"><span>${n}</span><kbd>${k}</kbd></div>`).join('')}</section></div></div></div>`}
function changes(){return `<div class="content">${heading('Review before you write','public.customers · Commerce · local',badge('Post-MVP concept','amber'))}<div class="callout warn" style="margin-bottom:24px">${icon('shield')}Row editing is a future workflow. These changes are simulated and target rows with a primary key.</div><div class="grid"><div class="card card-pad"><div class="eyebrow">Updates</div><div class="stat">1</div></div><div class="card card-pad"><div class="eyebrow">Inserts</div><div class="stat">0</div></div><div class="card card-pad"><div class="eyebrow">Deletes</div><div class="stat">1</div></div></div><div class="card" style="margin-top:25px"><table><thead><tr><th>Operation</th><th>Primary key</th><th>Column</th><th>Before</th><th>After</th></tr></thead><tbody><tr><td>${badge('Update')}</td><td class="mono">id = 4</td><td>plan</td><td>Starter</td><td>Pro</td></tr><tr><td>${badge('Delete','red')}</td><td class="mono">id = 7</td><td>Entire row</td><td>Orlando Diggs</td><td>—</td></tr></tbody></table></div><div class="card card-pad" style="margin-top:22px"><h3>SQL preview</h3><pre class="sql">BEGIN;
UPDATE public.customers SET plan = $1 WHERE id = $2;
-- Parameters: ['Pro', 4]
DELETE FROM public.customers WHERE id = $1;
-- Parameters: [7]</pre><p class="small">Changes run in a transaction. Review the result, then commit or roll back.</p></div><div class="actions" style="justify-content:flex-end;margin-top:22px">${link('Discard changes','workspace')}${btn('Apply 2 changes','apply-changes','primary')}</div></div>`}
const views={index:welcome,workspace,connection,schema,history,changes};shell((views[page]||welcome)());simplifyDesktopPage();
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.remove('hidden');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.add('hidden'),3300)}
let lastFocus, activeProfile;
function modal(title,body,actions=''){if(!document.querySelector('.modal'))lastFocus=document.activeElement;document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="row space"><h2 id="modal-title">${title}</h2>${btn(icon('close'),'close-modal','ghost')}</div>${body}<div class="actions">${actions||btn('Done','close-modal')}</div></section></div>`;document.querySelector('.mac-menubar').inert=true;document.querySelector('.shell').inert=true;document.querySelector('.modal input,.modal button,.modal a')?.focus()}
function closeModal(){if(document.querySelector('.export-dialog')){clearInterval(exportTimer);exportCancelled=true}document.getElementById('modal-root').innerHTML='';document.querySelector('.mac-menubar').inert=false;document.querySelector('.shell').inert=false;lastFocus?.focus()}
function esc(s){const e=document.createElement('span');e.textContent=s;return e.innerHTML}
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
let running=false,queryTimer,exportTimer,exportCancelled=false,disconnected=false;
function queryState(text,error=false){document.getElementById('query-state').innerHTML=`${icon(error?'help':'check')} ${text}`;document.getElementById('query-state').style.color=error?'var(--red)':'var(--green)'}
function runQuery(confirmed=false){if(running)return;if(disconnected){toast('Reconnect before running this query.');return}const sql=document.getElementById('sql-editor').innerText;if(!sql.trim()){toast('Write a query first.');return}if(!confirmed&&/\b(drop|truncate)\b|\b(update|delete)\b(?![\s\S]*\bwhere\b)/i.test(sql)){modal('Review this statement','<p>This statement may change or remove data. Review the SQL before continuing.</p><pre class="sql">'+esc(sql)+'</pre>',btn('Cancel','close-modal')+btn('Run simulated statement','confirm-run','primary'));return}running=true;queryState('Running…');document.querySelector('[data-action="cancel"]').classList.remove('hidden');document.querySelector('[data-action="run"]').disabled=true;queryTimer=setTimeout(()=>{running=false;document.querySelector('[data-action="cancel"]').classList.add('hidden');document.querySelector('[data-action="run"]').disabled=false;queryState('24 ms · Completed');document.getElementById('result-view').value='data';setResultView('data');recordQueryCompletion(sql);toast('Simulation complete. The grid displays fixed sample data.');},1400)}
function exportData(){const format=document.getElementById('export-format').value;const keys=['id','name','email','plan','status','created_at','total_spent'];const rows=customers.map(r=>Object.fromEntries(keys.map((k,i)=>[k,r[i]])));if(format==='JSON')return JSON.stringify(rows,null,2);if(format==='JSON Lines')return rows.map(r=>JSON.stringify(r)).join('\n');if(format==='SQL INSERT')return customers.map(r=>`INSERT INTO public.customers (${keys.join(', ')}) VALUES (${r.map(v=>v===null?'NULL':"'"+v.replaceAll("'","''")+"'").join(', ')});`).join('\n');const delim={ 'Comma ( , )':',','Semicolon ( ; )':';',Tab:'\t'}[document.getElementById('export-delimiter').value];return [...(document.getElementById('export-headers').checked?[keys]:[]),...customers].map(r=>r.map(v=>v===null?'':`"${v.replaceAll('"','""')}"`).join(delim)).join('\n')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(b.closest('form'))e.preventDefault();switch(a){
case 'new-connection':openConnection();break;
case 'connection-driver':{const form=document.getElementById('connection-form');const drafts=window.connectionDrafts||(window.connectionDrafts={});drafts[form.dataset.driver]=Object.fromEntries([...form.querySelectorAll('input')].filter(x=>x.type!=='password').map((x,i)=>[x.id||'input'+i,x.type==='checkbox'?x.checked:x.value]));form.outerHTML=connectionForm(b.dataset.driver==='sqlite');const draft=drafts[b.dataset.driver];if(draft)document.querySelectorAll('#connection-form input').forEach((x,i)=>{const v=draft[x.id||'input'+i];if(v!==undefined){if(x.type==='checkbox')x.checked=v;else x.value=v}});document.querySelector(`[data-action="connection-driver"][data-driver="${b.dataset.driver}"]`).focus();break;}
case 'open-export':openExportDialog();break;
case 'open-preferences':openPreferencesDialog(b.dataset.section);break;
case 'focus-connections':document.querySelector('.connection-option.selected')?.focus();break;
case 'connection-actions':openConnectionActions();break;
case 'select-connection':selectedConnection=explorerConnections.find(c=>c.id===b.dataset.connection)||explorerConnections[0];saved.explorerConnection=selectedConnection.id;persist();document.querySelector('.sidebar').outerHTML=sidebar();document.querySelector(`[data-connection="${selectedConnection.id}"]`).focus();break;
case 'close-modal':closeModal();break;
case 'command':modal('Go to…',`<label class="search">${icon('search')}<input id="command-search" placeholder="Find a screen…" aria-label="Find a screen"></label><nav class="menu-list" id="command-links" style="margin-top:16px">${Object.entries(names).map(([p,n])=>link(n+' →',p,'')).join('')}</nav>`);document.getElementById('command-search').focus();break;
case 'test-connection':if(!document.getElementById('connection-form').reportValidity())break;b.disabled=true;b.textContent='Testing…';setTimeout(()=>{if(!b.isConnected)return;document.getElementById('connection-feedback').innerHTML='<div class="callout">'+icon('check')+'Connection successful · simulated response in 38 ms</div>';b.disabled=false;b.textContent='Test connection'},850);break;
case 'connection-error':document.getElementById('connection-feedback').innerHTML='<div class="callout warn">Authentication failed · SQLSTATE 28P01<br>Check your username and password, then test again.</div>';break;
case 'save-profile':saveConnection();break;
case 'run':runQuery();break;case 'confirm-run':closeModal();runQuery(true);break;
case 'cancel':clearTimeout(queryTimer);queryState('Cancelling…');b.disabled=true;setTimeout(()=>{running=false;queryState('Cancelled · execution stopped');b.classList.add('hidden');b.disabled=false;document.querySelector('[data-action="run"]').disabled=false},500);break;
case 'query-error':queryState('Failed · 42P01',true);document.getElementById('messages-panel').innerHTML='<div class="callout warn">ERROR: relation “customer” does not exist<br>SQLSTATE 42P01 · Line 4, column 6<br>Try the qualified name public.customers.</div>';document.getElementById('result-view').value='messages';setResultView('messages');break;
case 'workspace-more':document.getElementById('workspace-tools').classList.toggle('hidden');b.setAttribute('aria-expanded',!document.getElementById('workspace-tools').classList.contains('hidden'));break;
case 'find':document.getElementById('findbar').classList.remove('hidden');document.getElementById('find-text').focus();break;case 'close-find':document.getElementById('findbar').classList.add('hidden');break;
case 'replace':{const from=document.getElementById('find-text').value;if(!from)break;const ed=document.getElementById('sql-editor');ed.textContent=ed.innerText.split(from).join(document.getElementById('replace-text').value);toast('Matching text replaced.');break;}
case 'new-query':newEditorDocument();break;
case 'save-sql':download('customer-overview.sql',document.getElementById('sql-editor').innerText);toast('SQL file prepared for download.');break;
case 'open-sql':{const input=document.createElement('input');input.type='file';input.accept='.sql,text/plain';input.onchange=async()=>{if(input.files[0]){document.getElementById('sql-editor').textContent=await input.files[0].text();toast('SQL opened without execution.')}};input.click();break;}
case 'copy-results':{const text=customers.map(r=>r.map(v=>v===null?'NULL':v).join('\t')).join('\n');if(navigator.clipboard)navigator.clipboard.writeText(text).then(()=>toast('Sample page copied as tab-separated text.')).catch(()=>modal('Copy result page','<textarea style="width:100%;height:220px">'+esc(text)+'</textarea>'));else modal('Copy result page','<textarea style="width:100%;height:220px">'+esc(text)+'</textarea>');break;}
case 'next-page':case 'prev-page':toast('All 8 sample rows are on page 1. No more rows to fetch.');break;
case 'query-settings':modal('Query settings',select('Run scope',['Selection or statement at cursor','Entire editor'])+field('Timeout (seconds)','30','number','min="1"')+select('Page size',['1,000 rows','100 rows','10,000 rows']),btn('Apply','apply-settings','primary'));break;
case 'apply-settings':closeModal();toast('Query settings applied for this preview.');break;
case 'commit':case 'rollback':toast(a==='commit'?'Sample transaction committed.':'Sample transaction rolled back.');break;
case 'disconnect':modal('Disconnect from Commerce?',`<p>${document.getElementById('transaction-mode').value==='Manual transaction'?'An open transaction will be rolled back. ':''}Editor text stays available. Reconnecting will not repeat any query.</p>`,btn('Keep connection','close-modal')+btn('Roll back & disconnect','confirm-disconnect','danger'));break;
case 'confirm-disconnect':clearTimeout(queryTimer);running=false;disconnected=true;closeModal();queryState('Disconnected · reconnect explicitly to run a query');document.querySelector('[data-action="run"]').disabled=true;document.querySelector('[data-action="cancel"]').classList.add('hidden');document.getElementById('query-state').insertAdjacentHTML('beforeend',btn('Reconnect','reconnect'));break;
case 'reconnect':disconnected=false;document.querySelector('[data-action="run"]').disabled=false;queryState('Connected · ready · no query executed');break;
case 'refresh':toast('Selected object refreshed from sample metadata.');break;
case 'schema-tab':{document.querySelectorAll('[data-action="schema-tab"]').forEach(x=>x.classList.toggle('active',x===b));const tab=b.dataset.tab;document.getElementById('schema-detail').innerHTML=tab==='Columns'?columns():tab==='Data'?dataTable():tab==='DDL'?'<pre class="sql card-pad">CREATE TABLE public.customers (\n  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  name varchar(255) NOT NULL,\n  email varchar(255) UNIQUE NOT NULL,\n  plan varchar(32) DEFAULT \'starter\',\n  status varchar(32) DEFAULT \'active\',\n  created_at timestamp DEFAULT now(),\n  total_spent numeric(12,2),\n  metadata jsonb DEFAULT \'{}\',\n  avatar bytea\n);</pre>':`<table><thead><tr><th>Name</th><th>Columns</th><th>Type</th></tr></thead><tbody><tr><td>customers_pkey</td><td class="mono">id</td><td>Primary key · B-tree</td></tr>${tab==='Indexes'?'<tr><td>customers_email_key</td><td class="mono">email</td><td>Unique · B-tree</td></tr>':''}</tbody></table>`;break;}
case 'generate-sql':modal('Generate SQL','<p>Open a statement in the editor. Nothing runs automatically.</p><div class="menu-list">'+['SELECT','INSERT','UPDATE','DELETE'].map(t=>`<button data-action="generated-sql" data-sql="${t}">${icon('code')} ${t} statement</button>`).join('')+'</div>');break;
case 'generated-sql':{const object=qualifiedObject();const sql={SELECT:`SELECT * FROM ${object} LIMIT 1000;`,INSERT:`INSERT INTO ${object} (name) VALUES ('');`,UPDATE:`UPDATE ${object} SET name = '' WHERE id = 1;`,DELETE:`DELETE FROM ${object} WHERE id = 1;`}[b.dataset.sql];queueObjectQuery(sql,object+' · '+b.dataset.sql);break;}
case 'history-open':{const item=b.closest('article')||document.querySelector('.history-item.selected-history:not([hidden])');if(!item){toast('Select a visible query first.');break}saved.pendingSQL=item.querySelector('.mono').textContent;saved.pendingTitle='History query';saved.pendingConnection=item.dataset.connection||'commerce';persist();location.href='workspace.html';break;}
case 'clear-history':modal('Clear query history?','<p>Remove the sample history from this view? Open editor tabs are kept.</p>',btn('Keep history','close-modal')+btn('Clear history','confirm-clear-history','danger'));break;
case 'confirm-clear-history':saved.executedQueries=[];persist();document.getElementById('history-list').innerHTML='<div class="empty">'+icon('history')+'<h2 style="margin-top:15px">A fresh page</h2><p>Your next queries will appear here.</p></div>';closeModal();break;
case 'start-export':{if(!document.getElementById('export-name').value.trim()){toast('Enter a file name.');break}exportCancelled=false;b.disabled=true;document.querySelector('[data-action="cancel-export"]').disabled=false;document.getElementById('export-progress').classList.remove('hidden');document.getElementById('export-status').textContent='Exporting sample rows…';let n=0;exportTimer=setInterval(()=>{n++;document.getElementById('export-bar').style.width=n/8*100+'%';document.getElementById('export-count').textContent=`${n} of 8 sample rows`;if(n===8){clearInterval(exportTimer);if(!exportCancelled){download(document.getElementById('export-name').value,exportData());document.getElementById('export-status').textContent='Export complete · download prepared';document.querySelector('[data-action="cancel-export"]').disabled=true;b.disabled=false;toast('Your sample export is ready.')}}},180);break;}
case 'cancel-export':b.disabled=true;clearInterval(exportTimer);exportCancelled=true;document.getElementById('export-status').textContent='Export cancelled · no file downloaded';document.querySelector('[data-action="start-export"]').disabled=false;break;
case 'export-error':document.querySelector('[data-action="cancel-export"]').disabled=true;clearInterval(exportTimer);document.getElementById('export-progress').classList.remove('hidden');document.getElementById('export-status').textContent='Export failed · destination is not writable';document.querySelector('[data-action="start-export"]').disabled=false;toast('Choose another destination and retry. No incomplete file was published.');break;
case 'save-preferences':{const root=document.querySelector('.preferences-dialog');const inputs=[...root.querySelectorAll('input')];const invalid=inputs.find(x=>!x.checkValidity());if(invalid){showPreferenceSection(invalid.closest('section').id);invalid.reportValidity();break}saved.preferences={};root.querySelectorAll('input,select').forEach((x,i)=>saved.preferences[x.id||'field'+i]=x.type==='checkbox'?x.checked:x.value);persist();applyEditorPreferences();closeModal();toast('Preferences saved on this browser.');break;}
case 'apply-changes':modal('Apply 2 changes?','<p>Update customer 4 and delete customer 7 in a simulated transaction. Review the result before committing.</p>',btn('Cancel','close-modal')+btn('Apply changes','confirm-changes','primary'));break;
case 'confirm-changes':modal('Changes applied · transaction open','<div class="callout">2 sample rows affected. Commit to finish or roll back to discard the changes.</div>',btn('Roll back','finish-rollback')+btn('Commit changes','finish-commit','primary'));break;
case 'finish-rollback':case 'finish-commit':closeModal();toast(a==='finish-commit'?'Sample changes committed.':'Sample changes rolled back.');document.querySelector('[data-action="apply-changes"]').disabled=true;break;
}});
document.addEventListener('input',e=>{if(e.target.id==='tree-search')document.querySelectorAll('.table-node').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(e.target.value.toLowerCase()));if(e.target.id==='connection-search')document.querySelectorAll('.connection-card').forEach(x=>x.hidden=!x.dataset.name.includes(e.target.value.toLowerCase()));if(e.target.id==='history-search')filterHistory();if(e.target.id==='command-search')document.querySelectorAll('#command-links a').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(e.target.value.toLowerCase()))});
function filterHistory(){document.querySelectorAll('.history-item').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(document.getElementById('history-search').value.toLowerCase())||(document.getElementById('history-status').value!=='All statuses'&&x.dataset.status!==document.getElementById('history-status').value))}
document.addEventListener('change',e=>{if(e.target.id==='result-view')setResultView(e.target.value);if(e.target.id==='history-status')filterHistory();if(e.target.id==='theme'){saved.theme=e.target.value;document.body.classList.toggle('dark',saved.theme==='Dark'||saved.theme==='System'&&matchMedia('(prefers-color-scheme: dark)').matches);persist()}if(e.target.id==='transaction-mode')document.getElementById('transaction-actions').classList.toggle('hidden',e.target.value!=='Manual transaction');if(e.target.id.startsWith('export-')){const f=document.getElementById('export-format').value;if(e.target.id==='export-format')document.getElementById('export-name').value='customers-september.'+{CSV:'csv',JSON:'json','JSON Lines':'jsonl','SQL INSERT':'sql'}[f];document.getElementById('csv-options').classList.toggle('hidden',f!=='CSV');document.getElementById('export-headers').closest('.settings-row').hidden=f!=='CSV';document.getElementById('export-preview').textContent=exportData().slice(0,420)}});
document.addEventListener('submit',e=>{if(e.target.id==='connection-form'){e.preventDefault();saveConnection(true)}});
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(a&&/^connection\.html(?:[?#]|$)/.test(a.getAttribute('href'))){e.preventDefault();openConnection(new URL(a.href).searchParams.get('driver')==='sqlite')}});
document.addEventListener('input',e=>{if(e.target.id==='profile-name')e.target.setCustomValidity('')});
if(page==='connection')openConnection(new URLSearchParams(location.search).get('driver')==='sqlite');
document.addEventListener('dblclick',e=>{const cell=e.target.closest('#results-table td');if(!cell)return;modal('Value inspector',`<div class="row" style="margin:16px 0">${badge('Text','')}<span class="small muted">public.customers · sample value</span></div><pre class="sql" style="padding:18px;background:var(--soft);border-radius:8px">${esc(cell.textContent)}</pre><p class="small" style="margin-top:16px">Large text and binary values load in bounded segments in the native app.</p>`)});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&document.querySelector('.modal')){const elements=[...document.querySelectorAll('.modal button,.modal a,.modal input,.modal select,.modal textarea')].filter(x=>!x.disabled&&!x.hidden&&x.getClientRects().length);const first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}if(e.metaKey||e.ctrlKey){if(document.querySelector('.modal'))return;const act=e.key==='k'?'command':page==='workspace'?(e.key==='Enter'?'run':e.key==='f'?'find':e.key==='s'?'save-sql':null):null;if(act){e.preventDefault();invokeMenu(act)}}});
if(page==='workspace'){if(saved.pendingSQL){window.incomingDocument={sql:saved.pendingSQL,title:saved.pendingTitle,connection:saved.pendingConnection};delete saved.pendingTitle;delete saved.pendingConnection;document.getElementById('sql-editor').textContent=saved.pendingSQL;delete saved.pendingSQL;persist();queryState('Ready · opened SQL has not been executed');document.getElementById('data-panel').classList.add('hidden')}if(new URLSearchParams(location.search).get('query')==='revenue')document.getElementById('sql-editor').textContent="-- Revenue by month\nSELECT date_trunc('month', created_at) AS month,\n       SUM(total) AS revenue\nFROM public.orders\nGROUP BY 1\nORDER BY 1 DESC;";if(saved.preferences){const p=saved.preferences;document.getElementById('sql-editor').style.fontSize=(p['editor-size']||13)+'px';if(p['line-numbers']===false)document.querySelector('.line-numbers').style.visibility='hidden'}}


function setResultView(view){document.getElementById('data-panel').classList.toggle('hidden',view!=='data');document.getElementById('messages-panel').classList.toggle('hidden',view!=='messages')}

let menuTrigger=null,menuSelection=null;
function closeAppMenu(restore=false){document.getElementById('app-menu-popup')?.remove();document.querySelectorAll('[data-app-menu]').forEach(b=>b.setAttribute('aria-expanded','false'));if(restore)menuTrigger?.focus()}
function openAppMenu(trigger){
  const selected=window.getSelection();if(selected?.rangeCount&&document.getElementById('sql-editor')?.contains(selected.anchorNode))menuSelection=selected.getRangeAt(0).cloneRange();
  closeAppMenu();menuTrigger=trigger;trigger.setAttribute('aria-expanded','true');
  const popup=document.createElement('div');popup.id='app-menu-popup';popup.className='app-menu-popup';popup.setAttribute('role','menu');popup.setAttribute('aria-label',trigger.dataset.appMenu);
  popup.innerHTML=applicationMenus[trigger.dataset.appMenu].map(([label,action,shortcut])=>`<button role="menuitem" data-menu-command="${action}" tabindex="-1"><span>${label}</span>${shortcut?`<span class="menu-shortcut">${shortcut}</span>`:''}</button>`).join('');document.body.append(popup);const rect=trigger.getBoundingClientRect();popup.style.left=Math.min(rect.left,innerWidth-265)+'px';popup.style.top=rect.bottom+'px';popup.querySelector('button').focus();
}
function invokeMenu(action){
  if(action.startsWith('@')){location.href=action.slice(1)+'.html';return}
  if(action==='about'){modal('ChoscorDB','<p>A local-first PostgreSQL and SQLite client.</p><p class="small">Interactive design prototype. Database operations use sample data.</p>',btn('Close','close-modal'));return}
  if(action.startsWith('edit-')){const ed=document.getElementById('sql-editor');if(!ed){toast('Open the SQL editor to edit a query.');return}ed.focus();if(menuSelection){const selection=window.getSelection();selection.removeAllRanges();selection.addRange(menuSelection)}if(action==='edit-select-all'){const range=document.createRange();range.selectNodeContents(ed);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range)}else if(action==='edit-copy'){const text=window.getSelection().toString();if(!text){toast('Select text in the editor first.');return}navigator.clipboard?.writeText(text).then(()=>toast('Selected SQL copied.')).catch(()=>toast('Use the keyboard copy shortcut.'))}else document.execCommand(action==='edit-undo'?'undo':'redo');return}
  const workspaceActions=['new-query','open-sql','save-sql','find','run','cancel','query-settings','manual-transaction','commit','rollback','disconnect'];
  if(workspaceActions.includes(action)&&page!=='workspace'){saved.pendingMenuAction=action;persist();location.href='workspace.html';return}
  if(action==='manual-transaction'){document.getElementById('workspace-tools').classList.remove('hidden');document.getElementById('transaction-mode').value='Manual transaction';document.getElementById('transaction-mode').dispatchEvent(new Event('change',{bubbles:true}));return}
  if(['commit','rollback'].includes(action)&&document.getElementById('transaction-mode').value!=='Manual transaction'){toast('Choose Query → Manual transaction first.');return}
  const control=document.querySelector(`[data-action="${action}"]`);
  if(control){if(control.disabled||(action==='cancel'&&control.classList.contains('hidden'))){toast('This action is not available in the current query state.');return}control.click()}else{const proxy=document.createElement('button');proxy.dataset.action=action;proxy.hidden=true;document.body.append(proxy);proxy.click();proxy.remove()}
}
document.addEventListener('click',e=>{const trigger=e.target.closest('[data-app-menu]');if(trigger){const open=trigger.getAttribute('aria-expanded')==='true';if(open)closeAppMenu(true);else openAppMenu(trigger);return}const item=e.target.closest('[data-menu-command]');if(item){const action=item.dataset.menuCommand;closeAppMenu();invokeMenu(action);return}if(!e.target.closest('#app-menu-popup'))closeAppMenu()});
document.addEventListener('keydown',e=>{
  const popup=document.getElementById('app-menu-popup'),trigger=e.target.closest('[data-app-menu]');
  if(!popup&&!trigger)return;
  if(e.key==='Escape'){e.preventDefault();closeAppMenu(true);return}
  if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const triggers=[...document.querySelectorAll('[data-app-menu]')];const current=trigger||menuTrigger;const next=triggers[(triggers.indexOf(current)+(e.key==='ArrowRight'?1:-1)+triggers.length)%triggers.length];triggers.forEach(x=>x.tabIndex=x===next?0:-1);if(popup)openAppMenu(next);else next.focus();return}
  if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();if(!popup){openAppMenu(trigger);return}const items=[...popup.querySelectorAll('button')];let index=items.indexOf(document.activeElement);index=e.key==='Home'?0:e.key==='End'?items.length-1:(index+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items[index].focus()}
  if(e.key==='Tab')closeAppMenu();
});
if(page==='workspace'&&saved.pendingMenuAction){const action=saved.pendingMenuAction;delete saved.pendingMenuAction;persist();if(!['run','cancel','commit','rollback','disconnect'].includes(action))invokeMenu(action)}
// Match the file/application shortcuts advertised in the menu bar.
document.addEventListener('keydown',e=>{
  if(!(e.metaKey||e.ctrlKey)||document.querySelector('.modal'))return;
  const action={n:'new-connection',t:'new-query',o:'open-sql',',':'open-preferences'}[e.key.toLowerCase()];
  if(action){e.preventDefault();closeAppMenu();invokeMenu(action)}
});

initializeFlow();
